/**
 * Unit tests for GJChronology.getInstance
 */
public class GJChronology_getInstance_TriageGen0Test {

    @Test
    public void testGetInstance_NullCutover_UTC() {
        // Tests the branch where gregorianCutover is null and zone is UTC
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.UTC, null, 4);
        assertNotNull(chrono);
        assertEquals(DateTimeZone.UTC, chrono.getZone());
        // Since it's UTC, it should follow the specific UTC branch logic
    }

    @Test
    public void testGetInstance_NullCutover_NonUTC() {
        // Tests the branch where gregorianCutover is null and zone is non-UTC
        GJChronology chrono = GJChronology.getInstance(DateTimeZone.getProvider().getPerceivedTimeZone(), null, 4);
        assertNotNull(chrono);
        assertEquals(DateTimeZone.getProvider().getPerceivedTimeZone(), chrono.getZone());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetInstance_WithCutover_ThrowsException() {
        // The provided code has a hardcoded 'if (true)' block that throws IllegalArgumentException
        // This test ensures we cover that branch.
        ReadableInstant cutover = new Instant();
        GJChronology.getInstance(DateTimeZone.UTC, cutover, 4);
    }

    @Test
    public void testGetInstance_CacheHit() {
        // To test the cache hit, we need to bypass the 'if (true)' exception.
        // NOTE: In the provided source code, the 'if (true)' block makes it impossible 
        // to reach the cache logic if gregorianCutover is NOT null.
        // However, if gregorianCutover IS null, it goes to the cache logic.

        // First call to populate cache
        GJChronology chrono1 = GJChronology.getInstance(DateTimeZone.UTC, null, 4);

        // Second call to hit cache
        GJChronology chrono2 = GJChronology.getInstance(DateTimeZone.UTC, null, 4);

        assertSame("Should return the same instance from cache", chrono1, chrono2);
    }

    @Test
    public void testGetInstance_CacheMiss_NewList() {
        // Tests the branch where chronos == null (first time a zone is accessed)
        // We use a unique zone to ensure a new list is created in the cache
        DateTimeZone customZone = DateTimeZone.forID("Asia/Tokyo");
        GJChronology chrono = GJChronology.getInstance(customZone, null, 4);

        assertNotNull(chrono);
        assertEquals(customZone, chrono.getZone());
    }

    @Test
    public void testGetInstance_DifferentParams_CacheMiss() {
        // Tests the branch where the loop in the cache finds no match 
        // (different minDaysInFirstWeek or different cutover)

        // We use null cutover to avoid the 'if (true)' exception
        GJChronology chrono1 = GJChronology.getInstance(DateTimeZone.UTC, null, 4);
        GJChronology chrono2 = GJChronology.getInstance(DateTimeZone.UTC, null, 5);

        assertNotSame("Should be different instances due to different minDaysInFirstWeek", chrono1, chrono2);
    }
}
